INSERT INTO `catalog_product_flat_28` VALUES (187,4,'simple',4,'Black',NULL,'2025-06-02 02:58:09',NULL,2,0,'//a/u/autocad-3d-design-drawing-and-modeling.jpg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0','test',NULL,NULL,500.0000,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,39,'45cm','test',NULL,'//a/u/autocad-3d-design-drawing-and-modeling.jpg',NULL,0,NULL,NULL,NULL,NULL,'//a/u/autocad-3d-design-drawing-and-modeling.jpg',2,'//a/u/autocad-3d-design-drawing-and-modeling.jpg',NULL,'2025-06-17 02:16:49','testja',NULL,4,NULL,NULL),(206,4,'configurable',NULL,NULL,NULL,'2025-06-06 07:03:31','<style>#html-body [data-pb-style=JVQCWKK]{justify-content:flex-start;display:flex;flex-direction:column;background-position:left top;background-size:cover;background-repeat:no-repeat;background-attachment:scroll}</style><div data-content-type=\"row\" data-appearance=\"contained\" data-element=\"main\"><div data-enable-parallax=\"0\" data-parallax-speed=\"0.5\" data-background-images=\"{}\" data-background-type=\"image\" data-video-loop=\"true\" data-video-play-only-visible=\"true\" data-video-lazy-load=\"true\" data-video-fallback-src=\"\" data-element=\"inner\" data-pb-style=\"JVQCWKK\"><div data-content-type=\"text\" data-appearance=\"default\" data-element=\"main\"><p id=\"I7W6HJJ\"><strong>Adobe Creative Cloud for Single App – ทางเลือกคุ้มค่าสำหรับสายครีเอทีฟที่ต้องการใช้แอปเดียว</strong><br>Adobe Creative Cloud for Single App คือโซลูชันที่ออกแบบมาเพื่อผู้ใช้งานที่ต้องการใช้งานเพียงหนึ่งแอปพลิเคชันจาก Adobe เช่น Photoshop, Illustrator, Premiere Pro, After Effects หรือ InDesign โดยไม่จำเป็นต้องสมัครสมาชิกแบบครบชุด เหมาะสำหรับฟรีแลนซ์ นักออกแบบ นักตัดต่อวิดีโอ หรือธุรกิจขนาดเล็กที่ต้องการควบคุมต้นทุน พร้อมใช้งานซอฟต์แวร์ลิขสิทธิ์แท้จาก Adobe อย่างมั่นใจ</p></div></div></div>',2,1,'//p/r/product-software-adobe-cc-single-apps_1.png',NULL,49,'Subscription (รายเดือน/ปี)',NULL,NULL,NULL,40,'Adobe',NULL,'0','Adobe Creative Cloud for Single App',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'<